// server/bootRetry.ts
var BOOT_RETRY_FIRST_MS = 15e3;
var BOOT_RETRY_MAX_MS = 5 * 6e4;
function bootRetryDelay(attempt) {
  const doubled = BOOT_RETRY_FIRST_MS * 2 ** Math.max(0, attempt - 1);
  return Math.min(doubled, BOOT_RETRY_MAX_MS);
}
function retryBoot(options) {
  const schedule3 = options.schedule ?? ((fn, ms3) => setTimeout(fn, ms3));
  let stopped = false;
  let attempt = 0;
  const next = () => {
    attempt += 1;
    schedule3(() => void run3(), bootRetryDelay(attempt));
  };
  const run3 = async () => {
    if (stopped) return;
    let value;
    try {
      value = await options.attempt();
    } catch (error) {
      if (stopped) return;
      const failure = error instanceof Error ? error : new Error(String(error));
      options.onFailed?.(attempt, failure, bootRetryDelay(attempt + 1));
      next();
      return;
    }
    if (stopped) return;
    stopped = true;
    await options.onRecovered(value);
  };
  next();
  return () => {
    stopped = true;
  };
}

