// server/services/puzzle/maturity.ts
init_types2();
function readMaturity(input) {
  const out = [];
  const qualified = new Set(
    input.qualifications.filter((one) => one.verdict === "QUALIFIED").map((one) => one.productId)
  );
  for (const format of input.formats) {
    if (format.retiredAt !== null) continue;
    const key = format.formatKey;
    const implementation = formatFor(key);
    const masters = input.masters.filter((one) => one.formatKey === key);
    const masterIds = new Set(masters.map((one) => one.id));
    const valid = input.instances.filter(
      (one) => masterIds.has(one.masterId) && one.validationState === "VALID"
    );
    const products = input.products.filter(
      (one) => masterIds.has(one.masterId) && one.retiredAt === null
    );
    const qualifiedProducts = products.filter((one) => qualified.has(one.id));
    const demand = input.demand.filter((one) => one.formatKey === key);
    const channels = input.routes.filter((one) => one.formatKey === key && one.kind === "CHANNEL");
    const production = input.routes.filter(
      (one) => one.formatKey === key && one.kind === "PRODUCTION"
    );
    const mine = input.observations.filter((one) => one.formatKey === key);
    const settled2 = products.filter(
      (one) => one.opportunityId !== null && input.settledOpportunityIds.has(one.opportunityId)
    );
    const editRequired = implementation?.requiresHumanEdit ?? true;
    const edited = mine.some((one) => one.kind === "HUMAN_EDIT_PASSED");
    const playtested = mine.some((one) => one.kind === "PLAYTEST_RESULT");
    const steps = [
      { name: "DISCOVERED", met: true, blocked: "", who: "NOTHING" },
      {
        name: "RESEARCHED",
        met: demand.length > 0 || channels.length > 0,
        blocked: "No published buyer and no published channel. A question about who actually pays for this format is the next thing, and it is the cheapest thing here.",
        who: "RESEARCH"
      },
      {
        name: "GENERATABLE",
        met: implementation?.render != null,
        blocked: implementation ? `${implementation.title} is authored rather than generated here: its content is editorial work with no correctness criterion, so there is a validator and deliberately no generator. Somebody writes one and Brain checks it.` : "Nothing in this repository generates this format. Building a generator and a validator for it is a code change somebody reviews.",
        who: implementation ? "PERSON" : "CODE"
      },
      {
        name: "VALIDATABLE",
        met: valid.length > 0,
        blocked: masters.length === 0 ? "A generator exists and no puzzle system has been set up from it yet." : "A system exists and nothing it made has passed validation. The failing checks are recorded against each refused seed, and what they point at is the generator.",
        who: masters.length === 0 ? "PERSON" : "CODE"
      },
      {
        name: "PRODUCTIZABLE",
        met: qualifiedProducts.length > 0,
        blocked: products.length === 0 ? `${valid.length} validated puzzle(s) and nothing compiled into a product yet.` : "Every product compiled from this format is substantially the same puzzles in the same shape as another. A distinct output needs new content, or a real difference of audience, difficulty, occasion, language, format, channel or buyer.",
        who: "PERSON"
      },
      {
        name: "SELLABLE",
        met: channels.length > 0 && (edited || !editRequired && playtested),
        blocked: channels.length === 0 ? "There is a product and no published route to a buyer. Which marketplace, syndicate, distributor or retailer takes this, and on what terms, is a question." : editRequired ? "This format needs a person to read what was made before any of it is sold, and no such reading is recorded. There is no flag that stands in for it." : "Nobody has read or played a sample of what this system produces. A machine check establishes that a puzzle is solvable and cannot establish that it is any good, and the brief asks for a look at every new template.",
        who: channels.length === 0 ? "RESEARCH" : "PERSON"
      },
      {
        name: "REVENUE_PROVEN",
        met: settled2.length > 0,
        blocked: "Nothing has been paid for. A settled entry in the money ledger is the only thing that moves this, and an agreement, an acceptance or an invoice is not one.",
        who: "MONEY"
      },
      {
        name: "REPEATABLE",
        met: settled2.length > 1,
        blocked: "One sale is a sale. Two from this format, through a route that stayed available, is the difference between something that worked and something that works.",
        who: "MONEY"
      },
      {
        name: "SCALABLE",
        met: settled2.length > 1 && qualifiedProducts.length > 2,
        blocked: "Repeat revenue exists and the catalog behind it is thin. Scaling means more distinct outputs from the same system reaching the same route, not more copies of one.",
        who: "PERSON"
      },
      {
        name: "PRODUCTION_OWNED",
        met: production.length > 0 && input.heldCapabilities.length > 0,
        blocked: production.length === 0 ? "Nobody has established who physically makes this, so ownership is not yet a question with a shape." : "Production is outsourced. Owning it is the manufacturing programme\u2019s decision and its capital arithmetic, not this kernel\u2019s \u2014 and it is only worth asking once the outsourced version is reliably profitable.",
        who: "PERSON"
      }
    ];
    const reached = [];
    let rung = "DISCOVERED";
    let waitingOn = "Nothing. This format is fully realised on every rung this ladder has.";
    let remedy = "NOTHING";
    for (const one of steps) {
      if (!one.met) {
        waitingOn = one.blocked;
        remedy = one.who;
        break;
      }
      reached.push(one.name);
      rung = one.name;
    }
    out.push({
      formatKey: key,
      name: format.name,
      rung,
      waitingOn,
      remedy,
      reached,
      evidence: {
        validPuzzles: valid.length,
        products: qualifiedProducts.length,
        buyers: demand.length,
        channels: channels.length
      },
      limitation: implementation?.limitation ?? null
    });
  }
  const weight = (one) => one.evidence.validPuzzles + one.evidence.products * 10 + one.evidence.buyers * 10 + one.evidence.channels * 10;
  return out.sort((a, b) => {
    const rank5 = (one) => PUZZLE_MATURITY_RUNGS.indexOf(one.rung);
    return rank5(b) - rank5(a) || weight(b) - weight(a) || a.name.localeCompare(b.name);
  });
}

