async function adoptSurface(input) {
  const user = await getUser(input.userId);
  if (!user) return { ok: false, reason: "No such person." };
  const routine = await getRoutineByRef(input.routineRef.trim());
  if (!routine) {
    return {
      ok: false,
      reason: `No registered Routine has the reference ${input.routineRef.trim()}. Register it with \`fleet register-routine\` first, or check the reference on the Fleet page.`
    };
  }
  if (routine.state === "RETIRED") {
    return {
      ok: false,
      reason: `${routine.name} is retired, so nothing is fired at it. Adopting a surface Brain does not use would record a connection that cannot be proved.`
    };
  }
  if (!routine.workerId) {
    return {
      ok: false,
      reason: `${routine.name} is not bound to a worker, so there is no identity to adopt. \`fleet bind-worker\` is what records one, and it is an operator\u2019s decision.`
    };
  }
  const existing = await connectionForUser(input.userId);
  if (existing && existing.routineId && existing.routineId !== routine.id) {
    return {
      ok: false,
      reason: "This person already has a surface recorded. Giving one back is theirs to do \u2014 the Revoke control on their own page \u2014 and it keeps its history rather than being overwritten here."
    };
  }
  if (existing && existing.routineId === routine.id) {
    return { ok: true, connection: existing, alreadyAdopted: true };
  }
  const claimed = (await listConnections()).find(
    (one) => one.routineId === routine.id && one.revokedAt === null
  );
  if (claimed) {
    return {
      ok: false,
      reason: `${routine.name} is already recorded as somebody else\u2019s connection. A surface belongs to one person, and moving it would be the defect this is repairing, with an audit row on it.`
    };
  }
  const names = namesFor(user);
  const connection = existing ?? await ensureConnection({
    userId: input.userId,
    connectorName: names.connectorName,
    routineName: names.routineName,
    secretName: names.secretName
  });
  const account = await getAccount(routine.accountId);
  const written = await setAdoptedSurface({
    connectionId: connection.id,
    accountId: routine.accountId,
    routineId: routine.id,
    workerId: routine.workerId,
    routineName: routine.name,
    secretName: routine.tokenSecretName,
    triggerRef: routine.routineRef
  });
  if (!written) {
    const now = await connectionForUser(input.userId);
    return now && now.routineId === routine.id ? { ok: true, connection: now, alreadyAdopted: true } : { ok: false, reason: "That connection changed while this was being recorded. Read it again." };
  }
  const fresh = await connectionForUser(input.userId);
  if (fresh && fresh.state !== "CONFIGURED" && fresh.state !== "HEALTHY") {
    await moveConnection({ connectionId: fresh.id, from: fresh.state, to: "CONFIGURED" });
  }
  await recordIdentityEvent({
    actorType: "HUMAN",
    actorId: input.actorUserId,
    action: "ADOPT_CAPACITY_SURFACE",
    targetType: "WORKER",
    targetId: routine.workerId,
    result: "SUCCESS",
    metadata: {
      connectionId: connection.id,
      forUserId: input.userId,
      routineId: routine.id,
      routineRef: routine.routineRef,
      accountName: account?.name ?? null,
      // How the call got in, never assumed to be the stronger one.
      authorityChannel: input.channel ?? "SHELL"
    }
  });
  const after = await connectionForUser(input.userId) ?? connection;
  return { ok: true, connection: after, alreadyAdopted: false };
}

