// server/services/identity/recoveryContract.ts
var RETIRED_BY_RECOVERY = ["PASSKEY", "PIN", "SESSION"];
function recoveryRetiresEverything(holdings) {
  const held = [];
  if (holdings.hasPin) held.push("PIN");
  if (holdings.livePasskeys > 0) held.push("PASSKEY");
  const uncovered = held.filter((one) => !RETIRED_BY_RECOVERY.includes(one));
  if (uncovered.length === 0) {
    return {
      complete: true,
      uncovered: [],
      because: held.length === 0 ? "This account holds no credential, so a recovery has nothing to retire and issues a link that sets one." : `A recovery retires everything this account holds (${held.join(", ").toLowerCase()}) before the replacement link can be redeemed.`,
      remedy: ""
    };
  }
  return {
    complete: false,
    uncovered,
    because: `A recovery would not retire this account's ${uncovered.join(" or ").toLowerCase()}, so whoever prompted the recovery would still be able to sign in afterwards.`,
    remedy: `Retire ${uncovered.join(" and ").toLowerCase()} in issueRecovery, beside the passkeys and sessions it already ends.`
  };
}

// server/services/identity/foundation.ts
init_people();
function pass(dimension2, because) {
  return { dimension: dimension2, verdict: "PASS", because, nextAction: null, owner: "NOBODY" };
}
function blocked(dimension2, because, nextAction3, owner) {
  return { dimension: dimension2, verdict: "BLOCKED", because, nextAction: nextAction3, owner };
}
function notApplicable(dimension2, because) {
  return { dimension: dimension2, verdict: "NOT_APPLICABLE", because, nextAction: null, owner: "NOBODY" };
}
async function foundationReading() {
  const all = await listUsers();
  const people = all.filter((one) => one.kind === "PERSON" && one.disabledAt === null);
  const capacity2 = await contributedCapacity();
  const nameCounts = ambiguousSignInNames(all);
  const accounts = [];
  for (const user of people) {
    const findings = await findingsFor(user, nameCounts, capacity2);
    accounts.push({
      userId: user.id,
      displayName: withoutDomain(user.displayName),
      isBrainAdmin: user.isBrainAdmin,
      findings,
      verdict: findings.some((one) => one.verdict === "BLOCKED") ? "BLOCKED" : "PASS"
    });
  }
  return {
    accounts,
    passing: accounts.filter((one) => one.verdict === "PASS").length,
    blocked: accounts.filter((one) => one.verdict === "BLOCKED").length,
    unattributed: await unattributedSurfaces()
  };
}
async function unattributedSurfaces() {
  const routines = await listRoutines();
  const out = [];
  for (const routine of routines) {
    if (routine.state === "RETIRED") continue;
    if (routine.workerId === null) continue;
    const worker = await getWorker(routine.workerId);
    if (!worker || worker.archived) continue;
    if (worker.ownerUserId !== null) continue;
    out.push({
      routineId: routine.id,
      routineName: routine.name,
      workerId: worker.id,
      workerLabel: worker.label,
      enabled: routine.state === "ENABLED",
      because: "This surface is bound to a worker identity no member\u2019s connection resolves to, so the sessions it runs cannot be attributed to any account.",
      nextAction: "Adopt it by having its owner complete the connection journey and repointing the Routine to the worker that mints, or retire the surface with fleet set-state. Both are an operator\u2019s decision; nothing here changes a live binding."
    });
  }
  return out;
}
async function findingsFor(user, nameCounts, capacity2) {
  const names = namesFor(user);
  const connection = await connectionForUser(user.id);
  const worker = await workerFor(connection, names.workerName);
  const routine = connection?.routineId ? await getRoutine(connection.routineId) : null;
  const surface = capacity2.surfaces.find((one) => one.userId === user.id) ?? null;
  const findings = [];
  const sharing = (nameCounts.get(signInName(user.displayName)) ?? 1) - 1;
  if (sharing > 0) {
    findings.push(
      blocked(
        "IDENTITY",
        `${sharing + 1} accounts share the display name \u201C${withoutDomain(user.displayName)}\u201D, so typing it at the sign-in screen resolves to none of them.`,
        "Rename all but one of them, so the name identifies exactly one account.",
        "BRAIN_ADMINISTRATOR"
      )
    );
  } else {
    findings.push(
      pass(
        "IDENTITY",
        "One account, named unambiguously, so the name resolves at the sign-in screen."
      )
    );
  }
  const livePasskeys = await countLivePasskeys(user.id);
  if (user.pinUpdatedAt !== null) {
    findings.push(pass("SIGN_IN", "A PIN is set, which is what the sign-in screen asks for."));
  } else if (user.passwordUpdatedAt !== null) {
    findings.push(
      blocked(
        "SIGN_IN",
        "This account signs in with a password. It works, but the intended ordinary credential is a six-digit PIN, and the password stays only as the way back in.",
        /*
         * The exact address, because nothing links to it.
         *
         * `/recovery` is deliberately unlinked — an alternative credential on
         * the front door teaches everybody that this Brain has passwords — so
         * a remedy that said "the account page" would name a screen that does
         * not do this, which is the remedy-for-a-condition-that-was-never-true
         * defect §27 records.
         */
        "Open /recovery, sign in with the password, and set a six-digit PIN. The password keeps working for exactly that.",
        "MEMBER"
      )
    );
  } else if (livePasskeys > 0) {
    findings.push(
      blocked(
        "SIGN_IN",
        "This account holds a passkey and no PIN. The served sign-in screen asks for a PIN and offers no way to present a device, so it cannot get in.",
        "Issue a recovery link from People & capacity; redeeming it ends in setting a PIN.",
        "BRAIN_ADMINISTRATOR"
      )
    );
  } else {
    findings.push(
      blocked(
        "SIGN_IN",
        "This account holds no credential of any kind, so nobody can sign in as it.",
        "Issue an enrollment link from People & capacity; redeeming it ends in setting a PIN.",
        "BRAIN_ADMINISTRATOR"
      )
    );
  }
  if (!connection) {
    findings.push(
      notApplicable(
        "CLAUDE_CONNECTION",
        "No connection has been started, so there is no lifecycle to be wrong about."
      )
    );
  } else if (connection.state === "HEALTHY") {
    findings.push(
      pass("CLAUDE_CONNECTION", "A session Brain fired arrived, was assigned work and finished it.")
    );
  } else if (connection.state === "REVOKED") {
    findings.push(
      blocked(
        "CLAUDE_CONNECTION",
        "This connection was taken back, so Brain does not fire it.",
        "Reconnect it from the connection page, which re-approves the same worker.",
        "MEMBER"
      )
    );
  } else if (connection.state === "MISBOUND") {
    findings.push(
      blocked(
        "CLAUDE_CONNECTION",
        "The registered surface is not the one this connection names, so its sessions would be attributed to another worker.",
        `Repoint it with: fleet repoint-worker --ref ${connection.triggerRef ?? "<trigger>"}`,
        "BRAIN_ADMINISTRATOR"
      )
    );
  } else if (connection.state === "WAITING_FOR_ADMIN") {
    findings.push(
      blocked(
        "CLAUDE_CONNECTION",
        `The surface is registered and ${connection.secretName} is not set in this deployment, so a fire would be refused.`,
        `Set ${connection.secretName} in the deployment environment. Brain resumes by itself.`,
        "DEPLOYMENT_ADMINISTRATOR"
      )
    );
  } else if (connection.state === "INVITATION_REQUESTED") {
    findings.push(
      blocked(
        "CLAUDE_CONNECTION",
        "This member has asked for a connector link and has not been issued one.",
        "Issue the Claude connector link from the member list on People & capacity.",
        "BRAIN_ADMINISTRATOR"
      )
    );
  } else {
    findings.push(
      blocked(
        "CLAUDE_CONNECTION",
        `The connection is at ${connection.state}, which is short of proven.`,
        "Open the connection page, which names the one step that is outstanding.",
        "MEMBER"
      )
    );
  }
  if (!connection) {
    findings.push(
      notApplicable("WORKER_ATTRIBUTION", "No connection, so no worker identity to attribute.")
    );
  } else if (!worker) {
    findings.push(
      blocked(
        "WORKER_ATTRIBUTION",
        `No worker identity named ${names.workerName} exists yet, so nothing this member runs could be attributed to them.`,
        "Issue the Claude connector link, which is what mints the identity.",
        "BRAIN_ADMINISTRATOR"
      )
    );
  } else if (worker.archived) {
    findings.push(
      blocked(
        "WORKER_ATTRIBUTION",
        `This member\u2019s worker identity is archived, which is terminal.`,
        "A Brain administrator resolves an archived identity; nothing in the flow can un-archive one.",
        "BRAIN_ADMINISTRATOR"
      )
    );
  } else if (routine && routine.workerId !== null && routine.workerId !== worker.id) {
    findings.push(
      blocked(
        "WORKER_ATTRIBUTION",
        "The registered Routine is bound to a different worker, so this member\u2019s sessions would be recorded as somebody else\u2019s.",
        `Repoint it with: fleet repoint-worker --ref ${connection.triggerRef ?? "<trigger>"}`,
        "BRAIN_ADMINISTRATOR"
      )
    );
  } else if (!routine) {
    findings.push(
      blocked(
        "WORKER_ATTRIBUTION",
        "A worker identity exists and no Routine is registered against it, so there is no surface whose sessions could be attributed.",
        "Submit the Routine\u2019s trigger id on the connection page.",
        "MEMBER"
      )
    );
  } else {
    findings.push(
      pass(
        "WORKER_ATTRIBUTION",
        "The registered surface is bound to this member\u2019s own worker identity."
      )
    );
  }
  if (!connection) {
    findings.push(
      notApplicable("CAPACITY", "No connection, so there is no capacity to be usable or not.")
    );
  } else if (surface?.usable) {
    findings.push(pass("CAPACITY", "The dispatcher would fire this surface."));
  } else {
    findings.push(
      blocked(
        "CAPACITY",
        /*
         * The reason comes from `contribution.ts` rather than being restated.
         *
         * It is the module that decides usability, it already answers with the
         * remedy in the sentence, and a second wording here would eventually
         * describe a different rule from the one being applied.
         */
        surface?.because ?? "This connection is not capacity the dispatcher would fire.",
        "Follow the reason above; the connection page names the same step.",
        "MEMBER"
      )
    );
  }
  const retires = recoveryRetiresEverything({
    hasPin: user.pinUpdatedAt !== null,
    livePasskeys
  });
  if (retires.complete) {
    findings.push(
      pass(
        "RECOVERY",
        "An administrator can issue a recovery link, and it retires everything this account currently holds before the replacement is redeemed."
      )
    );
  } else {
    findings.push(
      blocked(
        "RECOVERY",
        retires.because,
        retires.remedy,
        "BRAIN_ADMINISTRATOR"
      )
    );
  }
  return findings;
}

