function digestCaptures(captures) {
  const hash4 = createHash30("sha256");
  const ordered = [...captures].sort(
    (a, b) => `${a.surfaceKey}|${a.width}|${a.artifactRef}`.localeCompare(`${b.surfaceKey}|${b.width}|${b.artifactRef}`)
  );
  for (const capture3 of ordered) {
    hash4.update(`${capture3.surfaceKey}|${capture3.width}|${capture3.artifactRef}|`);
    hash4.update(capture3.contentHash);
    hash4.update("\n");
  }
  return { digest: hash4.digest("hex"), count: ordered.length };
}

