async function bootstrapFirstAdmin() {
  const email = read5("BRAIN_BOOTSTRAP_ADMIN_EMAIL");
  const password = read5("BRAIN_BOOTSTRAP_ADMIN_PASSWORD");
  if (!email && !password) {
    return { created: false, reset: false, email: null, reason: null };
  }
  if (!email || !password) {
    return {
      created: false,
      reset: false,
      email: null,
      reason: "BRAIN_BOOTSTRAP_ADMIN_EMAIL and BRAIN_BOOTSTRAP_ADMIN_PASSWORD must both be set, or neither."
    };
  }
  const forced = (read5("BRAIN_BOOTSTRAP_ADMIN_RESET") ?? "").toLowerCase();
  const forceReset = forced === "1" || forced === "true" || forced === "yes";
  const existing = await getUserByEmail(email);
  if (existing && (existing.mustChangePassword || forceReset)) {
    try {
      await setUserPassword(existing.id, password, { mustChangePassword: false });
    } catch (error) {
      if (error instanceof WeakPasswordError) {
        return { created: false, reset: false, email: null, reason: error.message };
      }
      throw error;
    }
    if (!existing.isBrainAdmin) await setBrainAdmin(existing.id, true);
    if (existing.disabled) await setUserDisabled(existing.id, false);
    return { created: false, reset: true, email: existing.email, reason: null };
  }
  if (existing) {
    return {
      created: false,
      reset: false,
      email: null,
      reason: `${existing.email} already has a password somebody chose. Set BRAIN_BOOTSTRAP_ADMIN_RESET=true alongside the other two variables to replace it, then remove all three.`
    };
  }
  if (await countUsers() > 0) {
    return {
      created: false,
      reset: false,
      email: null,
      reason: "this Brain already has accounts, so the bootstrap variables were ignored \u2014 remove them"
    };
  }
  try {
    const user = await createUser({
      email,
      /*
       * The address's local part, never the address.
       *
       * This line used to be `?? email`, and it is where the product's idea of
       * who its owner is came from: with `BRAIN_BOOTSTRAP_ADMIN_NAME` unset,
       * the first administrator was called `rosserpeyton@gmail.com` on every
       * screen, in every activity row and on the consent screen. A bootstrap
       * has no name to work from and must not invent one — so the fallback is
       * the honest shortening rather than a guess, and `people rename` is how
       * a real name arrives.
       */
      displayName: read5("BRAIN_BOOTSTRAP_ADMIN_NAME") ?? personName({ displayName: email }),
      password,
      isBrainAdmin: true,
      mustChangePassword: true,
      createdByType: "SYSTEM",
      createdById: "bootstrap"
    });
    return { created: true, reset: false, email: user.email, reason: null };
  } catch (error) {
    if (error instanceof WeakPasswordError) {
      return { created: false, reset: false, email: null, reason: error.message };
    }
    throw error;
  }
}
async function hasAnyAccount() {
  return await countUsers() > 0;
}

