        fragmentId: candidate.id,
        fragmentKey: candidate.fragment_key,
        orchestrationId: candidate.orchestration_id,
        host: candidate.block_host,
        probeBinId: reading.probeBinId,
        outcome: "REFUSED",
        reasons: error.reasons,
        newFragmentId: null
