// server/services/dispatch/lineageRecovery.ts
init_database();
init_fleet();
async function recoverExecutionLineage(limit = 25) {
  const bounded5 = Math.max(1, Math.min(200, limit));
  const report = { sessions: [], passes: [], unresolved: [] };
  const candidates = await getDb().all(
    /*
     * `GROUP BY` rather than `SELECT DISTINCT`, and the aggregate is named in
     * the select list rather than only in the ordering.
     *
     * Both are what makes one statement mean the same thing on both backends.
     * Postgres refuses an `ORDER BY` expression that is not in the select list
     * of a `SELECT DISTINCT`, so the first version of this ordering compiled,
     * passed on SQLite, and threw on the database production actually runs.
     */
    `SELECT p.executor_session_ref AS session_ref,
            p.executor_worker_id AS worker_id,
            MAX(p.started_at) AS newest
       FROM research_passes p
      WHERE p.executor_account_id IS NULL
        AND p.executor_worker_id IS NOT NULL
        AND p.executor_session_ref IS NOT NULL
        AND p.executor_session_ref <> ''
        AND p.executor_session_ref NOT LIKE 'future:%'
        AND NOT EXISTS (
          SELECT 1 FROM worker_sessions s WHERE s.session_ref = p.executor_session_ref
        )
      GROUP BY p.executor_session_ref, p.executor_worker_id
      /*
       * Newest first, by the most recent pass that refers to the session.
       *
       * Alphabetical order put a permanently unresolvable backlog at the front
       * of a bounded page and kept it there. What a reader of this wants is the
       * attribution that is missing *now*, and ordering by the work rather than
       * by the id is what makes the page reach it.
       */
      ORDER BY newest DESC, session_ref
      LIMIT ?`,
    [bounded5]
  );
  for (const candidate of candidates) {
    const fires = await getDb().all(
      `SELECT DISTINCT d.routine_id, d.bin_id, d.lease_generation
         FROM bins b
         JOIN bin_dispatch d ON d.bin_id = b.id
        WHERE b.lease_credential_id = ?
          AND b.worker_id = ?
          AND d.state = 'SENT'
          AND d.routine_id IS NOT NULL
          AND d.lease_generation < b.lease_generation

        UNION

       /*
        * The durable arm. work_leases keeps every claim this credential ever
        * made, and the arrival it followed is the newest BIN_ASSIGNED for
        * that bin, by that worker, at or before the claim \u2014 which is the same
        * pairing creditDispatchArrival makes live, reconstructed from the
        * events instead of from a column that has since been cleared.
        *
        * The generation arithmetic is that function's, unchanged: an
        * assignment reads the dispatch at the generation it is about to
        * supersede and then writes generation + 1, so the fire is at
        * e.lease_generation - 1.
        */
       SELECT DISTINCT d.routine_id, d.bin_id, d.lease_generation
         FROM work_leases wl
         JOIN work_items wi ON wi.id = wl.work_item_id
         /*
          * The queue's own bin-scope rule, not wi.bin_id alone.
          *
          * A bin naming an orchestration is a lease on that packet, so it
          * reaches the packet's untagged work \u2014 and research items are exactly
          * that: enqueueResearchItem sets orchestration_id and leaves
          * bin_id null. Joining on the column alone therefore matched none of
          * them, which is every audit pass there is, so the arm found nothing
          * for the one session it was written to recover.
          */
         JOIN bins b ON (wi.bin_id = b.id OR (wi.bin_id IS NULL AND wi.orchestration_id = b.orchestration_id))
         JOIN bin_events e ON e.bin_id = b.id
                          AND e.event_type = 'BIN_ASSIGNED'
                          AND e.worker_id = wl.worker_id
                          AND e.at <= wl.claimed_at
         JOIN bin_dispatch d ON d.bin_id = e.bin_id
                            AND d.lease_generation = e.lease_generation - 1
                            AND d.state = 'SENT'
                            AND d.routine_id IS NOT NULL
        WHERE wl.credential_id = ?
          AND wl.worker_id = ?
          AND e.at = (
            SELECT MAX(e2.at) FROM bin_events e2
             WHERE e2.bin_id = e.bin_id
               AND e2.event_type = 'BIN_ASSIGNED'
               AND e2.worker_id = wl.worker_id
               AND e2.at <= wl.claimed_at
          )

        ORDER BY 3`,
      [candidate.session_ref, candidate.worker_id, candidate.session_ref, candidate.worker_id]
    );
    if (fires.length === 0) {
      report.unresolved.push({
        sessionRef: candidate.session_ref,
        reason: "no dispatch Brain sent names a Routine for any bin this session took or claimed work in"
      });
      continue;
    }
    const routines = new Set(fires.map((fire) => fire.routine_id));
    if (routines.size > 1) {
      report.unresolved.push({
        sessionRef: candidate.session_ref,
        reason: `${routines.size} Routines fired the bins this session took, so which one started it is not established`
      });
      continue;
    }
    const first = fires[0];
    const routine = await getRoutine(first.routine_id);
    if (!routine?.accountId) {
      report.unresolved.push({
        sessionRef: candidate.session_ref,
        reason: "the Routine that fired it resolves to no account"
      });
      continue;
    }
    await recordWorkerSession({
      sessionRef: candidate.session_ref,
      workerId: candidate.worker_id,
      routineId: routine.id,
      accountId: routine.accountId,
      binId: first.bin_id,
      leaseGeneration: first.lease_generation
    });
    report.sessions.push({
      sessionRef: candidate.session_ref,
      routineId: routine.id,
      accountId: routine.accountId
    });
  }
  const passes = await getDb().all(
    /*
     * Only passes whose session is already observed, and newest first.
     *
     * The join is what stops the page being spent on rows nothing could
     * change: this used to select the oldest fifty unattributed passes and
     * then look each session up, and in production all fifty resolved to no
     * observation at all, so the page never advanced and the pass that needed
     * attributing sat behind them indefinitely.
     *
     * The worker still has to match, and that condition is here rather than
     * afterwards for the same reason. A credential that resolves to a
     * different worker than the pass recorded is a contradiction between two
     * rows, and filling one in from the other would settle it by preference.
     */
    `SELECT p.id, p.executor_worker_id, p.executor_session_ref, p.executor_routine_id,
            s.account_id AS observed_account_id, s.routine_id AS observed_routine_id
       FROM research_passes p
       JOIN worker_sessions s ON s.session_ref = p.executor_session_ref
                             AND s.worker_id = p.executor_worker_id
      WHERE p.executor_account_id IS NULL
        AND p.executor_worker_id IS NOT NULL
        AND p.executor_session_ref IS NOT NULL
        AND p.executor_session_ref <> ''
        AND p.executor_session_ref NOT LIKE 'future:%'
      ORDER BY p.started_at DESC, p.rowid DESC
      LIMIT ?`,
    [bounded5]
  );
  for (const pass2 of passes) {
    const observed = await getWorkerSession(pass2.executor_session_ref);
    if (!observed || observed.workerId !== pass2.executor_worker_id) continue;
    const result2 = await getDb().run(
      `UPDATE research_passes
          SET executor_account_id = ?,
              executor_routine_id = COALESCE(executor_routine_id, ?)
        WHERE id = ? AND executor_account_id IS NULL`,
      [observed.accountId, observed.routineId, pass2.id]
    );
    if (result2.changes === 1) {
      report.passes.push({ passId: pass2.id, accountId: observed.accountId });
    }
  }
  return report;
}

