// server/services/realize/director.ts
init_faculties2();
var RESEARCHABLE = ["MUST_BE_RESEARCHED"];
var REMEDY2 = {
  EXISTS_AND_LIVE: "nothing \u2014 it is already serving this requirement",
  EXISTS_BUT_DISCONNECTED: "wiring: the component exists and nothing reaches it",
  EXISTS_BUT_INSUFFICIENT: "a change to something that already exists",
  MUST_BE_BUILT: "implementation, through the Factory",
  MUST_BE_REPLACED: "implementation, replacing something that already exists",
  MUST_BE_RESEARCHED: "research: Brain does not know the answer and cannot read it from itself",
  REQUIRES_PERSON_AUTHORITY: "a person's decision, which no amount of building answers",
  NEEDS_A_READING: "a reading: somebody compares the requirement against the component"
};
function questionFor3(gap, faculty) {
  return {
    gapId: gap.id,
    key: `${faculty.slug.toLowerCase()}-${gap.aspect}-${gap.id.slice(-8)}`,
    statement: `For ${faculty.canonicalName}, establish from published sources what would satisfy this requirement: "${gap.requirement}". Brain's own reading of itself found: ${gap.evidence}`,
    aspect: gap.aspect,
    decides: "Whether this requirement can be served by something that already exists, and if not, what a bounded implementation of it would have to do. The answer decides whether a change request is made at all and what it asks for.",
    completionCriteria: [
      "a named, citable approach with a source that states it",
      "what it would cost to adopt, in the terms the source uses",
      "what it would not solve, stated rather than implied"
    ]
  };
}
async function directorPass(input) {
  const packet = await getPacket(input.packetId);
  if (!packet) throw new Error(`No such packet: ${input.packetId}`);
  const faculty = await getFaculty(packet.facultyId);
  if (!faculty) throw new Error(`Packet ${input.packetId} names a faculty that does not exist.`);
  const open = await listGaps(input.packetId, { states: ["OPEN"] });
  const notResearch = open.filter((gap) => !RESEARCHABLE.includes(gap.kind)).map((gap) => ({ gapId: gap.id, kind: gap.kind, remedy: REMEDY2[gap.kind] }));
  const researchable = open.filter((gap) => RESEARCHABLE.includes(gap.kind));
  if (researchable.length === 0) {
    return {
      packetId: input.packetId,
      researchable: 0,
      alreadyAnswered: 0,
      questions: [],
      notResearch,
      coverage: null,
      explanation: notResearch.length === 0 ? "Every gap on this packet is closed or waived, so there is nothing to research." : `Nothing here is a question about the world. ${notResearch.length} gap(s) are real and need something other than research.`
    };
  }
  const questions = researchable.map((gap) => questionFor3(gap, faculty));
  const coverage = await coverBeforeWork({
    projectId: input.projectId,
    layerId: input.layerId,
    requirements: questions.map((question) => ({
      key: question.key,
      statement: question.statement,
      completionCriteria: question.completionCriteria
    }))
  });
  const answeredKeys = new Set(coverage.answered.map((verdict) => verdict.requirementKey));
  for (const question of questions) {
    if (!answeredKeys.has(question.key)) continue;
    const verdict = coverage.answered.find((row) => row.requirementKey === question.key);
    await setGapState({
      gapId: question.gapId,
      state: "CLOSED",
      reason: `The archive already answers this. ${verdict?.reasons.join(" ") ?? ""} Claims: ${verdict?.claimIds.join(", ") ?? "none recorded"}. Researching it would spend the allowance to learn what Brain already knew.`
    });
  }
  const remaining = questions.filter((question) => !answeredKeys.has(question.key));
  return {
    packetId: input.packetId,
    researchable: researchable.length,
    alreadyAnswered: answeredKeys.size,
    questions: remaining,
    notResearch,
    coverage,
    explanation: explainCoverage(coverage)
  };
}
async function decisionReadiness(packetId) {
  const packet = await getPacket(packetId);
  if (!packet) throw new Error(`No such packet: ${packetId}`);
  const faculty = await getFaculty(packet.facultyId);
  const gaps = await listGaps(packetId);
  const open = gaps.filter((gap) => gap.state === "OPEN" || gap.state === "ASSIGNED");
  const stillResearching = open.filter((gap) => RESEARCHABLE.includes(gap.kind));
  const stillUnread = open.filter((gap) => gap.kind === "NEEDS_A_READING");
  const awaitingPerson = open.filter((gap) => gap.kind === "REQUIRES_PERSON_AUTHORITY");
  const buildable = open.filter(
    (gap) => gap.kind === "MUST_BE_BUILT" || gap.kind === "MUST_BE_REPLACED"
  );
  const conditions2 = [
    {
      clause: "the promised power is explicit",
      holds: Boolean(faculty?.definition.promisedPower),
      detail: faculty?.definition.promisedPower ?? "the faculty records no promised power, so there is nothing to build towards"
    },
    {
      clause: "every gap has been classified by a reading or a derivation",
      holds: stillUnread.length === 0,
      detail: stillUnread.length === 0 ? "nothing is waiting on somebody to compare a requirement against a component" : `${stillUnread.length} gap(s) still need a reading`
    },
    {
      clause: "no question about the world is still outstanding",
      holds: stillResearching.length === 0,
      detail: stillResearching.length === 0 ? "nothing is waiting on evidence" : `${stillResearching.length} question(s) are still open`
    },
    {
      clause: "every authority this needs has been granted",
      holds: awaitingPerson.length === 0,
      detail: awaitingPerson.length === 0 ? "nothing here waits on a decision only a person can make" : `${awaitingPerson.length} requirement(s) name an authority nobody has granted`
    },
    {
      clause: "there is something to build",
      holds: buildable.length > 0,
      detail: buildable.length > 0 ? `${buildable.length} gap(s) are classified as needing implementation` : "nothing is classified as needing to be built, so a change request would ask for nothing. That is a real outcome: this faculty needs connecting, evaluating or authorising rather than building."
    }
  ];
  const failed2 = conditions2.filter((condition) => !condition.holds);
  const decisionReady = failed2.length === 0;
  return {
    decisionReady,
    conditions: conditions2,
    reason: decisionReady ? "Every clause of the stopping condition holds: the promise is explicit, nothing is waiting on a reading, evidence or an authority, and there is something to build." : `Not decision-ready: ${failed2.map((condition) => condition.clause).join("; ")}.`,
    unresolved: [
      ...stillUnread.map((gap) => `needs a reading: ${gap.requirement}`),
      ...stillResearching.map((gap) => `needs evidence: ${gap.requirement}`),
      ...awaitingPerson.map((gap) => `needs a person: ${gap.requirement}`)
    ]
  };
}

// server/services/realize/compile.ts
var BUILDABLE = ["MUST_BE_BUILT", "MUST_BE_REPLACED"];
async function compile2(input) {
  const packet = await getPacket(input.packetId);
  if (!packet) return { ok: false, reason: `No such packet: ${input.packetId}`, unresolved: [] };
  const faculty = await getFaculty(packet.facultyId);
  if (!faculty) {
    return {
      ok: false,
      reason: `Packet ${input.packetId} names a faculty that does not exist.`,
      unresolved: []
    };
  }
  const readiness3 = await decisionReadiness(input.packetId);
  if (!readiness3.decisionReady) {
    return {
      ok: false,
      reason: `${readiness3.reason} A contract compiled over open questions asks for work nobody has established is the right work.`,
      unresolved: readiness3.unresolved
    };
  }
  const gaps = (await listGaps(input.packetId, { states: ["OPEN", "ASSIGNED"] })).filter(
    (gap) => BUILDABLE.includes(gap.kind)
  );
  if (gaps.length === 0) {
    return {
      ok: false,
      reason: "Nothing on this packet is classified as needing to be built, so there is nothing to ask for. A change request that asks for nothing is worse than none: somebody approves it and a campaign runs.",
      unresolved: []
    };
  }
  const sections = await currentSections(input.packetId);
  const contract = sections.find((row) => row.section === "COGNITIVE_CONTRACT");
  const topology = sections.find((row) => row.section === "TARGET_TOPOLOGY");
  const provenance = gaps.map((gap) => ({
    condition: conditionFor2(gap),
    gapId: gap.id,
    requirement: gap.requirement,
    aspect: gap.aspect
  }));
  const submission = {
    projectId: input.projectId,
    objective: `Implement the ${gaps.length} missing part(s) of ${faculty.canonicalName} that Brain's own reading of itself found: ${gaps.map((gap) => shortLabel(gap)).join("; ")}.`,
    expectedOutcome: faculty.definition.promisedPower,
    /*
     * Non-goals come from the faculty's own declared boundaries, plus the two
     * this kernel adds. Both of the added ones are refusals of things a
     * campaign could plausibly do that would make the result look finished
     * without being it — which is exactly what `fakeCompletionConditions` is
     * for, said where a builder will read it.
     */
    nonGoals: [
      ...faculty.definition.boundaries,
      "Moving any dimension on the faculty registry. A dimension moves because code ran and was evaluated, never because an implementation was merged.",
      "Adding a second orchestration path beside the ones this Brain already has. Every new mechanism is an entrance to existing machinery, not a parallel universe for it."
    ],
    acceptanceConditions: provenance.map((entry) => ({
      statement: entry.condition,
      verification: "A test that fails against the current tree and passes against the change, exercising the path a caller actually takes rather than a fixture that arranges its own starting state.",
      mandatory: true
    })),
    repositoryRemote: input.repositoryRemote,
    baseBranch: input.baseBranch,
    mutationScope: input.mutationScope
  };
  const carried = [];
  if (topology) carried.push(`Target topology (version ${topology.version}).`);
  if (contract) carried.push(`Cognitive contract (version ${contract.version}).`);
  if (carried.length > 0) {
    submission.objective += ` Designs this packet carries: ${carried.join(" ")}`;
  }
  return {
    ok: true,
    compiled: {
      submission,
      provenance,
      facultySlug: faculty.slug,
      packetId: input.packetId
    }
  };
}
function conditionFor2(gap) {
  const verb = gap.kind === "MUST_BE_REPLACED" ? "replaces what currently serves" : "serves";
  return `The change ${verb} this requirement, stated by the blueprint under "${gap.aspect}": "${gap.requirement}". [gap ${gap.id}]`;
}
function shortLabel(gap) {
  const trimmed = gap.requirement.replace(/\s+/g, " ").trim();
  return trimmed.length > 90 ? `${trimmed.slice(0, 87)}\u2026` : trimmed;
}

// server/services/realize/handoff.ts
async function handOff(input) {
  const existing = await getPacket(input.packetId);
  if (!existing) {
    return { ok: false, reason: `No such packet: ${input.packetId}`, unresolved: [] };
  }
  const outcome2 = await compile2({
    packetId: input.packetId,
    projectId: input.projectId,
    repositoryRemote: input.repositoryRemote,
    baseBranch: input.baseBranch,
    mutationScope: input.mutationScope
  });
  if (!outcome2.ok) return outcome2;
  let result2;
  try {
    result2 = await submitObjective(outcome2.compiled.submission);
  } catch (error) {
    if (error instanceof ContractError) {
      return {
        ok: false,
        reason: `The Factory refused the compiled contract: ${error.message} The packet is unchanged, so whatever is wrong can be corrected and handed off again.`,
        unresolved: []
      };
    }
    throw error;
  }
  const claimed = await getDb().run(
    `UPDATE realization_packets
        SET change_request_id = ?, updated_at = ?
      WHERE id = ? AND change_request_id IS NULL`,
    [result2.changeRequest.id, nowIso(), input.packetId]
  );
  if ((claimed.changes ?? 0) === 0) {
    const current = await getPacket(input.packetId);
    if (current?.changeRequestId === result2.changeRequest.id) {
      return {
        ok: true,
        changeRequest: result2.changeRequest,
        created: false,
        compiled: outcome2.compiled,
        packet: current
      };
    }
    return {
      ok: false,
      reason: `This packet already carries change request ${current?.changeRequestId ?? "unknown"}, and the contract compiled now is ${result2.changeRequest.id}. Two asks for one packet would put two decisions in front of a person for one question, so nothing was linked. The compiled contract still exists and can be approved on its own terms.`,
      unresolved: []
    };
  }
  const packet = await getPacket(input.packetId);
  return {
    ok: true,
    changeRequest: result2.changeRequest,
    created: result2.created,
    compiled: outcome2.compiled,
    packet: packet ?? existing
  };
}

