function suppressSqliteExperimentalWarning() {
  const original = process.emit.bind(process);
  const patched = (event, ...args) => {
    if (event === "warning") {
      const warning = args[0];
      if (warning instanceof Error && warning.name === "ExperimentalWarning" && warning.message.includes("SQLite is an experimental feature")) {
        return false;
      }
    }
    return original(event, ...args);
  };
  process.emit = patched;
}
suppressSqliteExperimentalWarning();
var CLIENT_DIST = path27.join(REPO_ROOT, "client", "dist");
