function installShutdown(server) {
  let closing = false;
  const shutdown = (signal) => {
    if (closing) return;
    closing = true;
    console.log(`[brain] ${signal} received \u2014 shutting down.`);
    server.close();
    void (async () => {
      await Promise.race([
        settleTokenTouches().catch(() => void 0),
        new Promise((resolve) => setTimeout(resolve, 3e3).unref())
      ]);
      try {
        await closeDatabase();
      } catch {
      }
      process.exit(0);
    })();
    setTimeout(() => process.exit(0), 5e3).unref();
  };
  process.on("SIGINT", () => shutdown("SIGINT"));
  process.on("SIGTERM", () => shutdown("SIGTERM"));
}
async function proveCloud() {
  try {
    await initStorage();
  } catch (error) {
    const failure = error instanceof Error ? error : new Error(String(error));
    console.error("");
    console.error("  Brain could not use the document storage it was configured for.");
    console.error("");
    console.error(`  ${failure.message}`);
    if (failure instanceof StorageConfigurationError && failure.detail) {
      console.error(`  ${failure.detail}`);
    }
    console.error("");
    console.error(
      "  Nothing was written to local disk instead: cloud storage does not fall back, because documents saved to this machine by a server reporting itself as cloud-backed are documents nobody else can open."
    );
    console.error("");
    throw failure;
  }
  try {
    return (await initDatabase()).migrations;
  } catch (error) {
    const failure = error instanceof Error ? error : new Error(String(error));
    console.error("");
    if (failure instanceof DatabaseConfigurationError) {
      console.error("  Brain could not use the database it was configured for.");
      console.error("");
      console.error(`  ${failure.message}`);
      if (failure.detail) console.error(`  ${failure.detail}`);
    } else {
      console.error("  Brain failed to migrate the database.");
      console.error("");
      console.error(`  ${failure.message}`);
      console.error("");
      console.error(`  Database  ${DB_PATH}`);
    }
    console.error(`  Data root ${DATA_ROOT}`);
    console.error("");
    throw failure;
  }
}
async function main() {
  ensureDataDirs();
  let migrations;
  try {
    migrations = await proveCloud();
  } catch (error) {
    const failure = error instanceof Error ? error : new Error(String(error));
    const failureServer = serveMigrationFailure(failure, { retrying: true });
    retryBoot({
      attempt: proveCloud,
      onFailed: (attempt, _error, nextDelayMs) => console.error(
        `[brain] Boot proof attempt ${attempt} failed; asking again in ${Math.round(nextDelayMs / 1e3)}s.`
      ),
      onRecovered: async (recovered) => {
        console.log("[brain] The cloud answered. Replacing the error page with the Brain.");
        failureServer.closeAllConnections();
        await new Promise((resolve) => failureServer.close(() => resolve()));
        await continueBoot(recovered);
      }
    });
    return;
  }
  await continueBoot(migrations);
}
var BOOT_STEP_WAIT_MS = 9e4;
async function afterListenStep(name, run3) {
  const started = Date.now();
  let timer7 = null;
  let movedOn = false;
  try {
    const step = run3();
    step.catch((error) => {
      if (movedOn) console.error(`[brain] boot step "${name}" failed after the boot moved on:`, error);
    });
    const bound3 = new Promise((resolve) => {
      timer7 = setTimeout(() => {
        movedOn = true;
        console.warn(`[brain] boot step "${name}" still running after ${BOOT_STEP_WAIT_MS / 1e3}s; continuing the boot beside it`);
        resolve(null);
      }, BOOT_STEP_WAIT_MS);
      timer7.unref?.();
    });
    return await Promise.race([step, bound3]);
  } catch (error) {
    console.error(`[brain] boot step "${name}" failed; serving on:`, error);
    return null;
  } finally {
    if (timer7) clearTimeout(timer7);
    const seconds = (Date.now() - started) / 1e3;
    if (seconds >= 1) console.log(`  boot: ${name} took ${seconds.toFixed(1)}s`);
  }
}
